const trigger = $input.first().json || {};
let name = String(trigger.contact_name || trigger.name || trigger.query || '').trim();
let conversation_id = trigger.conversation_id ? parseInt(trigger.conversation_id) : 0;
let account_id = trigger.account_id ? parseInt(trigger.account_id) : 1;

if (!name && trigger.query) {
  try {
    const qObj = typeof trigger.query === 'object' ? trigger.query : JSON.parse(trigger.query);
    if (qObj.contact_name) name = String(qObj.contact_name).trim();
    if (qObj.name) name = String(qObj.name).trim();
    if (qObj.conversation_id) conversation_id = parseInt(qObj.conversation_id);
  } catch(e) {}
}

name = name.replace(/^["']|["']$/g, '').trim();

return [{
  json: {
    raw_name: name,
    search_term: name,
    conversation_id: conversation_id,
    account_id: account_id
  }
}];

const resp = $input.first().json || {};
const prepData = $('Preparar Busqueda').first().json || {};
const searchTerm = (prepData.search_term || '').trim();

if (resp.status !== 'STATUS_SUCCESS' || !Array.isArray(resp.data) || resp.data.length === 0) {
  return [{
    json: {
      status: 'not_found',
      found: false,
      message: `No se encontraron líneas activas en MVPlay para "${searchTerm}".`,
      conversation_id: prepData.conversation_id,
      account_id: prepData.account_id
    }
  }];
}

const normalize = (str) => String(str || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const targetTokens = normalize(searchTerm).split(/\s+/).filter(t => t.length >= 2);

if (targetTokens.length === 0) {
  return [{
    json: {
      status: 'not_found',
      found: false,
      message: 'Nombre de búsqueda vacío o no válido.',
      conversation_id: prepData.conversation_id,
      account_id: prepData.account_id
    }
  }];
}

const lines = resp.data;
let bestMatch = null;
let bestScore = 0;

for (const line of lines) {
  const notesNorm = normalize(line.reseller_notes || '');
  const userNorm = normalize(line.username || '');

  let tokenMatches = 0;
  for (const t of targetTokens) {
    if (notesNorm.includes(t)) tokenMatches += 1;
    else if (userNorm.includes(t)) tokenMatches += 0.5;
  }

  if (tokenMatches === 0) continue;

  let score = tokenMatches * 10;
  if (notesNorm === normalize(searchTerm)) score += 50;
  else if (notesNorm.includes(normalize(searchTerm))) score += 30;

  if (String(line.is_trial) === '0') score += 20;
  if (String(line.enabled) === '1') score += 10;

  const lineId = parseInt(line.id, 10) || 0;
  score += (lineId / 10000000);

  if (score > bestScore) {
    bestScore = score;
    bestMatch = line;
  }
}

if (!bestMatch || bestScore === 0) {
  return [{
    json: {
      status: 'not_found',
      found: false,
      message: `No se encontraron coincidencias suficientes en MVPlay para "${searchTerm}".`,
      conversation_id: prepData.conversation_id,
      account_id: prepData.account_id
    }
  }];
}

const finalUser = bestMatch.username;
const finalPass = bestMatch.password;
const finalDns = 'http://wk.mvpl.uk:2082';
const finalDnsSmarters = 'http://cdn01link.uk:2095';
const finalNotes = bestMatch.reseller_notes || searchTerm;

// Enviar nota privada a Chatwoot si se cuenta con conversation_id
if (prepData.conversation_id) {
  try {
    const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
    const noteContent = `🤖 **CREDENCIALES RECUPERADAS (MVPlay / TVTotal24)**\n• Cliente: ${finalNotes}\n• Usuario: ${finalUser}\n• Contraseña: ${finalPass}\n• Servidor / DNS: ${finalDns}\n• DNS para Smarters: ${finalDnsSmarters}`;

    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/${prepData.account_id || 1}/conversations/${prepData.conversation_id}/messages`,
      headers: {
        'api_access_token': chatwootToken,
        'Content-Type': 'application/json'
      },
      body: {
        content: noteContent,
        private: true
      },
      json: true
    });
  } catch(e) {}
}

return [{
  json: {
    status: 'found',
    found: true,
    line_id: bestMatch.id,
    username: finalUser,
    password: finalPass,
    dns: finalDns,
    dns_smarters: finalDnsSmarters,
    exp_date: bestMatch.exp_date,
    is_trial: bestMatch.is_trial,
    reseller_notes: finalNotes,
    conversation_id: prepData.conversation_id,
    instructions_for_ai: "Entrega al cliente sus credenciales amablemente indicando Usuario, Contraseña, Servidor / DNS y DNS para Smarters. REGLA ESTRICTA: NO digas 'most apps' bajo ninguna circunstancia."
  }
}];

const item = $input.first().json || {};

if (item.found) {
  return [{
    json: {
      status: 'found',
      username: item.username,
      password: item.password,
      dns: item.dns,
      dns_smarters: item.dns_smarters,
      cliente: item.reseller_notes,
      instructions_for_ai: "Entrega al cliente sus credenciales amablemente indicando Usuario, Contraseña, Servidor / DNS y DNS para Smarters. REGLA ESTRICTA: NO digas 'most apps' bajo ninguna circunstancia."
    }
  }];
} else {
  return [{
    json: {
      status: 'not_found',
      message: item.message || 'No se encontraron credenciales activas en MVPlay para este cliente.',
      instructions_for_ai: 'Informa amablemente al cliente que no fue posible ubicar sus credenciales activas automáticamente en el sistema bajo ese nombre, y procede a transferirlo con un asesor humano ejecutando Call transfer_to_human_tool con reason Recuperacion de Credenciales.'
    }
  }];
}
